{"task": "Count suspicious injection attempts per HTTP status code to see which succeeded or failed", "sql": "SELECT status, COUNT(*) AS attempt_count FROM events WHERE regexp_like(path, '(union|select|insert|drop|update)\\s', 'i') GROUP BY status ORDER BY attempt_count DESC"}
{"task": "List distinct users whose request paths show SQL comment injection markers like -- or /*", "sql": "SELECT DISTINCT user_id FROM events WHERE regexp_like(path, '(--|#|/\\*)')"}
{"task": "Find paths attempting to extract database metadata via information_schema", "sql": "SELECT id, path FROM events WHERE regexp_like(path, 'information_schema', 'i')"}
