{"task": "Identify paths using hex or char encoding tricks often used to obfuscate injection payloads", "sql": "SELECT id, path FROM events WHERE regexp_like(path, '(0x[0-9a-f]+|char\\s*\\()', 'i')"}
{"task": "Rank the most frequent injection-like query string parameters across all paths to prioritise WAF rule tuning", "sql": "SELECT path, COUNT(*) AS occurrences FROM events WHERE regexp_like(path, '[?&][a-zA-Z0-9_]+=.*(select|union|drop|--)', 'i') GROUP BY path ORDER BY occurrences DESC LIMIT 20"}

